import org.junit.Test;
import static org.junit.Assert.*;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashMap;
import java.util.List;

import org.traccar.protocol.GalileoProtocolDecoder;
import org.traccar.helper.BitUtil;
import org.traccar.model.Position;
import org.traccar.protocol.GalileoProtocolDecoder.GalileoMessageTestHelper;
import org.traccar.protocol.GalileoProtocolDecoder.GalileoDecodeScenarioTestHelper;

public class GalileoProtocolDecoderTest {

    @Test
    public void decodeMessage_SimpleResponse() throws Exception {
        List<Byte> data = new ArrayList<>();
        data.add(0x01);
        data.add(0x02);

        GalileoMessageTestHelper helper = new GalileoMessageTestHelper(data);
        assertTrue(helper.decode());
    }

    @Test
    public void decodeMessage_NoMessage() throws Exception {
        List<Byte> data = new ArrayList<>();

        GalileoMessageTestHelper helper = new GalileoMessageTestHelper(data);
        assertFalse(helper.decode());
    }

    @Test
    public void decodePosition_ValidPosition() throws Exception {
        Date date = new Date();
        Position position = new Position(date, 0.0, 0.0);

        BitBuffer bitBuffer = new BitBuffer();
        bitBuffer.putByte(0x01);
        bitBuffer.putByte(0x02);

        GalileoDecodeScenarioTestHelper helper = new GalileoDecodeScenarioTestHelper(position, bitBuffer);
        assertTrue(helper.decode());
    }

    @Test
    public void decodePosition_NoDate() throws Exception {
        Date date = null;
        Position position = new Position(date, 0.0, 0.0);

        BitBuffer bitBuffer = new BitBuffer();
        bitBuffer.putByte(0x01);
        bitBuffer.putByte(0x02);

        GalileoDecodeScenarioTestHelper helper = new GalileoDecodeScenarioTestHelper(position, bitBuffer);
        assertFalse(helper.decode());
    }

    @Test
    public void decodeMessage_DateInvalid() throws Exception {
        Date date = new Date();
        Position position = new Position(date, 0.0, 0.0);

        BitBuffer bitBuffer = new BitBuffer();
        bitBuffer.putByte(0x01);
        bitBuffer.putByte(0x02);

        GalileoDecodeScenarioTestHelper helper = new GalileoDecodeScenarioTestHelper(position, bitBuffer);
        assertFalse(helper.decode());
    }

    @Test
    public void decodePosition_CoordinatesInvalid() throws Exception {
        Date date = new Date();
        Position position = new Position(date, -1.0, 0.0);

        BitBuffer bitBuffer = new BitBuffer();
        bitBuffer.putByte(0x01);
        bitBuffer.putByte(0x02);

        GalileoDecodeScenarioTestHelper helper = new GalileoDecodeScenarioTestHelper(position, bitBuffer);
        assertFalse(helper.decode());
    }

    @Test
    public void decodeMessage_InvalidPosition() throws Exception {
        Date date = new Date();
        Position position = null;

        BitBuffer bitBuffer = new BitBuffer();
        bitBuffer.putByte(0x01);
        bitBuffer.putByte(0x02);

        GalileoDecodeScenarioTestHelper helper = new GalileoDecodeScenarioTestHelper(position, bitBuffer);
        assertFalse(helper.decode());
    }
}
